import{_ as o,o as r,c as n,a5 as a}from"./chunks/framework.Cooo9kuv.js";const h=JSON.parse('{"title":"程序使用环境及相关说明","description":"","frontmatter":{"标题":"938-程序管理工具-文件管理工具-快捷键管理工具-文件夹管理工具","日期":"2026-05-21T00:00:00.000Z","修改日期":"2026-05-22T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["win系统问题","文件及文件夹批处理"],"标签":["分类管理","快捷启动","批量导入","文件快速打开","程序管理","网址收藏","脚本运行"]},"headers":[],"relativePath":"md/win系统问题/938-程序管理工具-文件管理工具-快捷键管理工具-文件夹管理工具.md","filePath":"md/win系统问题/938-程序管理工具-文件管理工具-快捷键管理工具-文件夹管理工具.md"}'),s={name:"md/win系统问题/938-程序管理工具-文件管理工具-快捷键管理工具-文件夹管理工具.md"};function p(e,t,d,g,l,c){return r(),n("div",null,[...t[0]||(t[0]=[a('<p>这是一个桌面快捷启动工具，帮你把常用的程序、文件、文件夹、网址、脚本集中管理，鼠标左键双击就能快速打开，再也不用在电脑里翻来翻去。</p><h2 id="快速上手-30秒看懂怎么用" tabindex="-1">快速上手（30秒看懂怎么用） <a class="header-anchor" href="#快速上手-30秒看懂怎么用" aria-label="Permalink to &quot;快速上手（30秒看懂怎么用）&quot;">​</a></h2><blockquote><p>写给急性子：只看这里就够了，3步走完</p></blockquote><p>1、<strong>启动工具</strong>：双击运行程序，主界面就弹出来了</p><p>2、<strong>添加快捷方式</strong>：点”＋ 添加”按钮，选一个你要快速打开的程序/文件/文件夹/网址，起个名字，确定</p><p>3、<strong>快速启动</strong>：以后想打开它，在界面上找到它，双击一下就行</p><p>搞定！就是这么简单。下面有详细说明，遇到问题往下翻。</p><p>支持软件、文件夹、网址的一键启动，提供网格和列表两种视图模式，内置分类管理和软链接功能。</p><p>支持拖拽排序和双击启动，首次运行自动注入 36 个 Windows 常用系统工具（Win7+）。</p><p>通过全局快捷键（Ctrl+Space）快速唤出，支持系统托盘最小化，粘贴导入文件和网址，批量导入文件夹。</p><p>配置数据自动存放于程序同目录，适用于 Windows 系统。</p><h2 id="适用人群" tabindex="-1">适用人群 <a class="header-anchor" href="#适用人群" aria-label="Permalink to &quot;适用人群&quot;">​</a></h2><p>这个工具适合谁用？</p><p><strong>上班族</strong>：每天要打开很多办公软件和文档，不想每次都在开始菜单里找半天</p><p><strong>设计师</strong>：常用设计软件、素材文件夹、参考网站太多，想统一管理快速调用</p><p><strong>电脑爱好者</strong>：经常使用系统工具（注册表、组策略、磁盘管理等），希望一键直达</p><hr><h2 id="解决的痛点" tabindex="-1">解决的痛点 <a class="header-anchor" href="#解决的痛点" aria-label="Permalink to &quot;解决的痛点&quot;">​</a></h2><p>以前你可能是这样做的，又慢又麻烦：</p><table tabindex="0"><thead><tr><th>痛点</th><th>以前的做法</th><th>用这个工具后</th></tr></thead><tbody><tr><td>找个程序要翻半天</td><td>在开始菜单里一层层找，眼睛都花了</td><td>分类整理好，双击1秒打开</td></tr><tr><td>常用文件藏得太深</td><td>每次都要点进五六个文件夹才能找到</td><td>加到工具里，随时一键直达</td></tr><tr><td>常用文件藏得太深</td><td>每次都要点进五六个文件夹才能找到</td><td>加到工具里，随时一键直达</td></tr></tbody></table><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-9.png" alt=""></p><h2 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h2><p><strong>📂 分类管理</strong> — 左侧分类列表，支持添加、重命名、删除、拖拽排序</p><p><strong>🔍 快速搜索</strong> — 实时搜索过滤，支持一键清除按钮</p><p><strong>🖼️ 双视图模式</strong> — 网格模式（大图标+文本）和列表模式（图标+名称+路径），一键切换</p><p><strong>🔗 软链接支持</strong> — 文件/文件夹以符号链接形式添加，支持批量转换路径↔链接（默认启用）</p><p><strong>📋 粘贴导入</strong> — 支持 Ctrl+V 从剪贴板粘贴文件、文件夹、网址</p><p><strong>📥 批量导入</strong> — 支持同时选择文件夹和文件批量添加</p><p><strong>🖱️ 右键菜单</strong> — 打开、编辑、删除、移动分类、以管理员运行、打开方式、复制路径、打开文件位置</p><p><strong>🔄 拖拽排序</strong> — 网格和列表视图均支持拖拽重排项目顺序，数据自动保存</p><p><strong>👆 双击启动</strong> — 双击项目打开，单击选中，避免误操作</p><p><strong>🌐 浏览器选择</strong> — 支持以默认浏览器或指定浏览器（Edge/Chrome/Firefox/Brave/Opera）打开网址</p><p><strong>📄 打开方式</strong> — 支持记事本打开文本文件，系统打开方式对话框</p><p><strong>🎨 浅色主题</strong> — 默认浅色界面，简洁美观</p><p><strong>🖥️ 系统托盘</strong> — 关闭时最小化到托盘，支持托盘右键菜单</p><p><strong>⚡ 全局快捷键</strong> — 默认 Ctrl+Space 快速唤出/隐藏窗口</p><p><strong>🔧 默认系统工具</strong> — 首次运行自动注入 36 个 Windows 常用工具（回收站/注册表/组策略/控制面板/命令行等），支持一键恢复</p><p><strong>📊 软链接实时转换</strong> — 一键将现有项目在路径模式和软链接模式间批量转换</p><p><strong>💾 复制路径</strong> — 右键直接复制项目路径到剪贴板</p><p><strong>📁 打开文件位置</strong> — 右键在资源管理器中定位文件</p><p><strong>📋 高DPI支持</strong> — 兼容 2K/4K 分辨率</p><p><strong>Win7+ 兼容</strong> — 兼容 Windows 7 及以上所有版本</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-10.png" alt=""></p><h2 id="基本操作" tabindex="-1">基本操作 <a class="header-anchor" href="#基本操作" aria-label="Permalink to &quot;基本操作&quot;">​</a></h2><p>1、<strong>添加项目</strong> — 点击「＋ 添加」按钮或拖拽文件到窗口</p><p>2、<strong>粘贴导入</strong> — 复制文件/文件夹后按 Ctrl+V 或点击「📋 粘贴」</p><p>3、<strong>批量导入</strong> — 点击「导入」选择文件夹和文件</p><p>4、<strong>分类管理</strong> — 左侧分类列表右键可添加/重命名/删除，直接拖拽排序</p><p>5、<strong>切换视图</strong> — 点击「列表/网格」按钮切换显示模式</p><p>6、<strong>拖拽排序</strong> — 按住项目拖动到新位置即可重排，数据自动保存</p><p>7、<strong>双击启动</strong> — 双击项目打开，单击选中（避免误操作）</p><p>8、<strong>软链接</strong> — 点击「🔗 开启软连接/关闭软连接」按钮（默认开启），开启时导入的文件会创建符号链接</p><p>9、<strong>搜索</strong> — 顶部搜索框实时过滤项目，支持内置清除按钮</p><h2 id="右键菜单" tabindex="-1">右键菜单 <a class="header-anchor" href="#右键菜单" aria-label="Permalink to &quot;右键菜单&quot;">​</a></h2><p><strong>打开</strong> — 双击启动项目</p><p><strong>⚡ 以管理员身份运行</strong> — 程序和脚本专用</p><p><strong>打开方式</strong> — 选择默认浏览器或指定浏览器（Edge/Chrome/Firefox/Brave/Opera）打开网址；文本文件可用记事本打开；弹出系统打开方式对话框</p><p><strong>📋 复制路径</strong> — 复制项目完整路径到剪贴板</p><p><strong>📁 打开文件所在位置</strong> — 在资源管理器中定位并高亮文件</p><p><strong>编辑</strong> — 修改项目名称、路径、参数等</p><p><strong>移动到</strong> — 将项目移到其他分类</p><p><strong>删除</strong> — 删除项目</p><p><strong>🔄 刷新</strong> — 重新加载项目列表</p><p><strong>🔧 恢复默认工具</strong> — 一键恢复内置的 36 个 Windows 常用系统工具</p><h2 id="全局快捷键" tabindex="-1">全局快捷键 <a class="header-anchor" href="#全局快捷键" aria-label="Permalink to &quot;全局快捷键&quot;">​</a></h2><p><code>Ctrl+Space</code> — 唤出/隐藏窗口</p><p><code>Ctrl+V</code> — 粘贴文件/文件夹/网址</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p><strong>不要删除数据文件夹</strong>：<code>dawn_launcher_data</code> 文件夹保存了你的所有配置和快捷方式，删除后数据会丢失</p><p><strong>路径有效性</strong>：添加的快捷方式要确保路径是有效的，如果原文件被移动或删除，快捷方式会打不开</p><p><strong>管理员权限</strong>：某些系统工具（如注册表编辑器）需要管理员权限才能运行，右键选择”以管理员身份运行”</p><p><strong>符号链接权限</strong>：如果使用软链接模式，需要管理员权限或开启Windows开发者模式</p><p><strong>快捷键冲突</strong>：默认快捷键是Ctrl+Space，如果和其他软件冲突，可以在设置里改成别的组合键</p><p><strong>网址格式</strong>：添加网址时，要包含完整的协议头（<a href="http://xn--https-wm6j//%EF%BC%89%EF%BC%8C%E4%BE%8B%E5%A6%82%60https://www.baidu.com%60" target="_blank" rel="noreferrer">http://或https://），例如<code>https://www.baidu.com</code></a></p><p><strong>批量导入数量</strong>：一次性导入太多文件（几百个）可能会稍慢，建议分批导入</p><p><strong>定期备份</strong>：建议定期备份<code>dawn_launcher_data</code>文件夹，防止误删或系统故障导致数据丢失</p><h2 id="实际使用场景示例" tabindex="-1">实际使用场景示例 <a class="header-anchor" href="#实际使用场景示例" aria-label="Permalink to &quot;实际使用场景示例&quot;">​</a></h2><h3 id="场景1-上班族快速打开办公文档" tabindex="-1">场景1：上班族快速打开办公文档 <a class="header-anchor" href="#场景1-上班族快速打开办公文档" aria-label="Permalink to &quot;场景1：上班族快速打开办公文档&quot;">​</a></h3><p><strong>场景描述：</strong></p><p>小王每天都要打开同一个Excel表格做日报，但这个文件藏在”D:\\工作\\2024\\3月\\日报\\template.xlsx”，每次都要点五六次才能找到。</p><p><strong>操作步骤：</strong></p><p>启动工具，选择”办公”分类</p><p>点”＋ 添加”，填写：</p><p>名称：<code>日报模板</code></p><p>类型：<code>文件</code></p><p>路径：<code>D:\\工作\\2024\\3月\\日报\\template.xlsx</code></p><p>分类：<code>办公</code></p><p>点”确定”</p><p>以后每天早上，打开工具，在”办公”分类下双击”日报模板”就行</p><p><strong>预期结果：</strong></p><p>原来要翻5层文件夹才能找到的文件，现在双击1秒打开，每天节省2分钟。</p><hr><h2 id="场景2-设计师整理常用软件和素材库" tabindex="-1">场景2：设计师整理常用软件和素材库 <a class="header-anchor" href="#场景2-设计师整理常用软件和素材库" aria-label="Permalink to &quot;场景2：设计师整理常用软件和素材库&quot;">​</a></h2><p><strong>场景描述：</strong></p><p>设计师小李电脑上装了很多设计软件（Photoshop、Illustrator、Figma等），还有十几个素材文件夹和参考网站，每次开工都要找半天。</p><p><strong>操作步骤：</strong></p><p>在工具左侧点”＋ 添加”，新建一个分类叫”设计工具”</p><p><strong>添加常用软件：</strong></p><p>名称：<code>Photoshop</code>，类型：<code>程序</code>，路径：<code>C:\\Program Files\\Adobe\\Adobe Photoshop 2024\\Photoshop.exe</code></p><p>名称：<code>Illustrator</code>，类型：<code>程序</code>，路径：<code>C:\\Program Files\\Adobe\\Adobe Illustrator 2024\\Illustrator.exe</code></p><p><strong>点”导入”，批量添加素材文件夹：</strong></p><p>选择”设计工具”分类</p><p>点”导入”，选中所有素材文件夹</p><p><strong>添加参考网站：</strong></p><p>名称：<code>Dribbble</code>，类型：<code>网址</code>，路径：<code>https://dribbble.com</code></p><p>名称：<code>Behance</code>，类型：<code>网址</code>，路径：<code>https://www.behance.net</code></p><p><strong>预期结果：</strong></p><p>所有设计相关的软件、素材、网站都集中在”设计工具”分类下，开工时打开工具，点一下就能用，不用再到处找。</p><hr><h2 id="场景3-it人员快速调用系统管理工具" tabindex="-1">场景3：IT人员快速调用系统管理工具 <a class="header-anchor" href="#场景3-it人员快速调用系统管理工具" aria-label="Permalink to &quot;场景3：IT人员快速调用系统管理工具&quot;">​</a></h2><p><strong>场景描述：</strong></p><p>网管老张经常要用注册表编辑器、组策略、服务管理等系统工具，但这些工具藏得很深，每次都要Win+R然后输入命令，很麻烦。</p><p><strong>操作步骤：</strong></p><ol><li>首次启动工具时，系统已经自动添加了30多个常用系统工具到”默认工具”分类</li><li>直接打开工具，选择”默认工具”分类</li><li>找到你要用的工具，双击打开： <ul><li><code>注册表编辑器</code>：双击打开regedit</li><li><code>服务</code>：双击打开services.msc</li><li><code>任务管理器</code>：双击打开taskmgr</li><li><code>磁盘管理</code>：双击打开diskmgmt.msc</li></ul></li></ol><p><strong>预期结果：</strong></p><p>不用记那些复杂的命令（regedit、services.msc等），在工具里找到名字，双击就行。如果要以管理员身份运行，右键点击 → 选择”⚡ 以管理员身份运行”。</p><h2 id="数据存储位置" tabindex="-1">数据存储位置 <a class="header-anchor" href="#数据存储位置" aria-label="Permalink to &quot;数据存储位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>配置文件</td><td>程序同级目录下的 <code>dawn_launcher_data\\config.json</code></td></tr><tr><td>快捷方式数据</td><td>程序同级目录下的 <code>dawn_launcher_data\\data.json</code></td></tr><tr><td>软链接文件</td><td>程序同级目录下的 <code>dawn_launcher_data\\links\\</code> 文件夹</td></tr><tr><td>软链接文件</td><td>程序同级目录下的 <code>dawn_launcher_data\\links\\</code> 文件夹</td></tr></tbody></table><p><strong>重要提醒</strong>：<code>dawn_launcher_data</code> 文件夹保存了你所有的快捷方式配置，<strong>千万别删</strong>！如果想备份，把这个文件夹整个复制走就行。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: Dawn Launcher 是什么工具？</strong><br> A: Dawn Launcher 是一款免费的桌面程序管理快速启动工具。它可以帮助你将所有软件、文件夹和网址集中管理，通过网格或列表视图快速启动，支持分类管理（拖拽排序）、软链接、批量导入等功能。</p><p><strong>Q: Dawn Launcher 支持什么系统？</strong><br> A: 支持 Windows 7/8/10/11 系统，兼容 2K/4K 高DPI分辨率。只支持Windows 64位操作系统。</p><p><strong>Q: Dawn Launcher 的软链接功能是什么？</strong><br> A: 开启软链接模式后，添加文件/文件夹时会创建符号链接而非直接引用路径。这样可以集中管理文件引用，支持一键在路径模式和链接模式之间批量转换已有项目。软链接模式默认开启。</p><p><strong>Q: 如何快速添加程序到 Dawn Launcher？</strong><br> A: 支持多种方式：点击「＋ 添加」按钮手动添加、Ctrl+V 粘贴文件/文件夹/网址、点击「导入」批量选择文件和文件夹、从资源管理器拖拽文件。</p><p><strong>Q: Dawn Launcher 的快捷键是什么？</strong><br> A: 默认全局快捷键为 Ctrl+Space，可快速唤出/隐藏窗口。Ctrl+V 可粘贴剪贴板内容。快捷键可在设置中自定义。</p><p><strong>Q: 批量导入大量文件会卡顿吗？</strong><br> A: 不会。</p><p><strong>Q: 配置数据存在哪里？</strong><br> A: 配置数据存储在程序所在目录的 dawn_launcher_data/ 文件夹下，包括 config.json（设置）、data.json（项目数据）、links/（软链接）、dawn_launcher.log（日志）。打包为 exe 后会自动跟随 exe 目录。</p><p><strong>Q: Dawn Launcher 支持拖拽排序和双击启动吗？</strong><br> A: 支持。网格和列表视图均支持拖拽重排项目顺序，数据自动保存。双击项目即可启动，单击选中，有效避免误操作。</p><p><strong>Q: 默认系统工具有哪些？</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-11.png" alt=""></p><p>A: 首次运行自动注入 36 个 Windows 常用工具，<strong>涵盖系统管理</strong>（注册表/组策略/安全策略/计算机管理）、<strong>设备管理</strong>（设备管理器/磁盘管理）、<strong>服务管理</strong>（服务/任务计划/事件查看器/性能监视器）、<strong>网络管理</strong>（网络连接/防火墙/IE属性）、<strong>控制面板</strong>（系统属性/添加删除程序/桌面图标设置）、<strong>系统工具</strong>（命令提示符/PowerShell/MSConfig/DxDiag/截图/屏幕键盘/磁盘清理/资源监视器/系统信息）、<strong>其他</strong>（记事本/计算器/画图/系统还原/Windows功能/资源管理器）等。兼容 Windows 7 及以上版本。</p><p><strong>Q: 为什么有些程序图标显示不正常？</strong></p><p>A: 图标是从Windows系统自动获取的。如果图标显示异常，可能是：</p><ol><li>该文件本身没有图标（如.txt、.json等）</li><li>PIL库未安装（运行<code>pip install Pillow</code>安装）</li><li>程序会自动生成彩色图标作为替代，不影响使用</li></ol><p><strong>Q: 不小心删了快捷方式能恢复吗？</strong></p><p>A: 只要<code>dawn_launcher_data</code>文件夹还在，数据就不会丢。如果误删了：</p><ol><li>打开<code>dawn_launcher_data\\data.json</code>（用记事本或代码编辑器）</li><li>找到”items”数组，里面保存了所有快捷方式</li><li>如果文件被误改，可以用备份恢复</li></ol><p><strong>Q: 换个电脑怎么迁移数据？</strong></p><p>A: 很简单：</p><ol><li>在旧电脑上，把整个<code>dawn_launcher_data</code>文件夹复制到U盘</li><li>在新电脑上，把程序文件和<code>dawn_launcher_data</code>文件夹放在同一个相对位置</li><li>运行程序，所有快捷方式都还在</li></ol><h1 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h1><p><strong>1、适用的系统环境说明</strong>：</p><p>win7及以上64位windows操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：</p><p>①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p>**3、程序如何安装：**不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h1 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h1><p><strong>解压后直接使用即可，不需要安装，程序可以放在任意位置</strong></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2795.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2795.html</a></p>',151)])])}const _=o(s,[["render",p]]);export{h as __pageData,_ as default};
